      _cursor = null;
      ev.preventDefault();
      return true;
    }
    if (_throw) {
      log(`${bracketizeName(_throw.itemName)} throw cancelled.`);
      _throw = null;
      _cursor = null;
      ev.preventDefault();
      return true;
    }
    return false;
  }

  function _handleEnemyKeys(ev) {
    if (!_enemy) return false;

    if (ev.key === 'Tab') {
