import { defineComponent } from "../../lib/ecs-js/index.js";

export const SOCIAL_DISPOSITION_BANDS = Object.freeze({
  neutral: "neutral",
  suspicious: "suspicious",
  angry: "angry",
  hostile: "hostile",
});

/**
 * Per-subject memory of how one actor feels about another actor.
 * These records are child entities attached to the subject NPC/actor.
 */
export const SocialDisposition = defineComponent(
  "SocialDisposition",
  {
    subjectId: 0,
    targetId: 0,
    score: 0,
    band: SOCIAL_DISPOSITION_BANDS.neutral,
    reason: "",
    lastChangedTurn: 0,
    decayPerTurn: 1,
  },
  {
    validate(rec) {
      const band = String(rec?.band || "");
      return (
        typeof rec.subjectId === "number" &&
        rec.subjectId > 0 &&
        typeof rec.targetId === "number" &&
        rec.targetId > 0 &&
        typeof rec.score === "number" &&
        rec.score >= 0 &&
        Object.hasOwn(SOCIAL_DISPOSITION_BANDS, band) &&
        typeof rec.reason === "string" &&
        typeof rec.lastChangedTurn === "number" &&
        typeof rec.decayPerTurn === "number" &&
        rec.decayPerTurn >= 0
      );
    },
  },
);

