import { Faction } from "../components/Faction.js";
import { SocialDisposition } from "../components/SocialDisposition.js";
import { Vitality } from "../components/Vitality.js";
import {
  decaySocialDispositionRecord,
  isEntityHostile,
  isSocialActor,
  recordSocialOffense,
} from "../utils/socialDisposition.js";

const INSTALLED = Symbol.for("jshack:socialDisposition:listeners:installed");

function shopSeverityToDispositionAmount(ev) {
  return Math.max(0, Number(ev?.severity || 0) | 0) * 20;
}

function damageToDispositionAmount(ev) {
  const amount = Math.max(0, Number(ev?.amount ?? ev?.damage ?? 0));
  return Math.max(8, Math.min(60, Math.ceil(amount * 2)));
}

export function installSocialDispositionListeners(world) {
  if (!world || world[INSTALLED]) return;
  world[INSTALLED] = true;

  world.on("shop:claim-recorded", (ev = {}) => {
    const shopkeeperId = Number(ev.shopkeeperId || 0) | 0;
    const actorId = Number(ev.actorId ?? ev.actor ?? 0) | 0;
    recordSocialOffense(world, {
      subjectId: shopkeeperId,
      targetId: actorId,
      amount: shopSeverityToDispositionAmount(ev),
      reason: String(ev.reason || ev.claimKind || "shop_claim"),
      decayPerTurn: Number(ev.severity || 0) >= 4 ? 0.25 : 1,
    });
  });

  world.on("damaged", (ev = {}) => {
    const target = Number(ev.target || 0) | 0;
    const source = Number(ev.source || 0) | 0;
    if (!(target > 0) || !(source > 0) || target === source) return;
    if (!isSocialActor(world, target)) return;
    if (isEntityHostile(world, target, source)) return;
    recordSocialOffense(world, {
      subjectId: target,
      targetId: source,
      amount: damageToDispositionAmount(ev),
      reason: String(ev.cause || "damage"),
      decayPerTurn: 0.5,
    });
  });

  world.on("social:hostile-action", (ev = {}) => {
    const subjectId = Number(ev.subjectId || ev.targetId || 0) | 0;
    const actorId = Number(ev.actorId ?? ev.actor ?? 0) | 0;
    if (!(subjectId > 0) || !(actorId > 0)) return;
    if (!isSocialActor(world, subjectId)) return;
    recordSocialOffense(world, {
      subjectId,
      targetId: actorId,
      amount: Math.max(1, Number(ev.amount || 0) | 0),
      reason: String(ev.reason || "hostile_action"),
      decayPerTurn: Number.isFinite(Number(ev.decayPerTurn)) ? Number(ev.decayPerTurn) : 0.5,
    });
  });
}

export function socialDispositionSystem(world) {
  for (const [id, rec] of world.query(SocialDisposition)) {
    if (!world.isAlive(rec.subjectId) || !world.isAlive(rec.targetId)) continue;
    decaySocialDispositionRecord(world, id, rec);

    const vit = world.get(rec.subjectId, Vitality);
    if (vit && (vit.hp | 0) <= 0) continue;
    const fac = world.get(rec.subjectId, Faction);
    if (!fac) continue;
  }
}

