import { attach, children } from "../../lib/ecs-js/hierarchy.js";
import {
  AggroState,
  AGGRO_LEVELS,
  SEARCH_TURNS_HUNTING_GRACE,
} from "../components/AggroState.js";
import { Faction } from "../components/Faction.js";
import { Position } from "../components/Position.js";
import {
  SocialDisposition,
  SOCIAL_DISPOSITION_BANDS,
} from "../components/SocialDisposition.js";
import { areFactionsHostile } from "./factionHostility.js";
import { emitSafe } from "./emitSafe.js";

const NPC_FACTIONS = new Set(["shopkeeper", "townfolk", "neutral"]);

export function dispositionBand(score) {
  const value = Math.max(0, Number(score || 0));
  if (value >= 70) return SOCIAL_DISPOSITION_BANDS.hostile;
  if (value >= 40) return SOCIAL_DISPOSITION_BANDS.angry;
  if (value >= 15) return SOCIAL_DISPOSITION_BANDS.suspicious;
  return SOCIAL_DISPOSITION_BANDS.neutral;
}

export function isSocialActor(world, id) {
  const key = String(world.get(id, Faction)?.key || "").trim().toLowerCase();
  return NPC_FACTIONS.has(key);
}

export function findSocialDisposition(world, subjectId, targetId) {
  const subject = Number(subjectId || 0) | 0;
  const target = Number(targetId || 0) | 0;
  if (!(subject > 0) || !(target > 0)) return null;

  if (world?.isAlive?.(subject)) {
    for (const childId of children(world, subject)) {
      const rec = world.get(childId, SocialDisposition);
      if (rec && (rec.targetId | 0) === target) return { id: childId | 0, rec };
    }
  }

  for (const [id, rec] of world.query(SocialDisposition)) {
    if ((rec.subjectId | 0) === subject && (rec.targetId | 0) === target) return { id: id | 0, rec };
  }
  return null;
}

export function isEntityHostile(world, attackerId, defenderId) {
  const attacker = Number(attackerId || 0) | 0;
  const defender = Number(defenderId || 0) | 0;
  if (!(attacker > 0) || !(defender > 0) || attacker === defender) return false;

  const af = world.get(attacker, Faction)?.key || "";
  const df = world.get(defender, Faction)?.key || "";
  if (areFactionsHostile(af, df)) return true;

  const found = findSocialDisposition(world, attacker, defender);
  return found?.rec?.band === SOCIAL_DISPOSITION_BANDS.hostile;
}

function aimAggroAtTarget(world, subjectId, targetId) {
  const aggro = world.get(subjectId, AggroState);
  if (!aggro) return;
  const pos = world.get(targetId, Position);
  if (pos) {
    aggro.lastKnownX = pos.x | 0;
    aggro.lastKnownY = pos.y | 0;
  }
  aggro.alertLevel = AGGRO_LEVELS.hunting;
  aggro.searchTurnsLeft = SEARCH_TURNS_HUNTING_GRACE;
  aggro.retreating = false;
}

export function recordSocialOffense(world, spec = {}) {
  const subjectId = Number(spec.subjectId || 0) | 0;
  const targetId = Number(spec.targetId || spec.actorId || spec.actor || 0) | 0;
  if (!(subjectId > 0) || !(targetId > 0) || subjectId === targetId) return null;
  if (!world?.isAlive?.(subjectId) || !world?.isAlive?.(targetId)) return null;

  const amount = Math.max(0, Math.ceil(Number(spec.amount || 0)));
  if (amount <= 0) return null;

  let found = findSocialDisposition(world, subjectId, targetId);
  if (!found) {
    const id = world.create();
    world.add(id, SocialDisposition, {
      subjectId,
      targetId,
      score: 0,
      band: SOCIAL_DISPOSITION_BANDS.neutral,
      reason: "",
      lastChangedTurn: Number(world.step || 0) | 0,
      decayPerTurn: Math.max(0, Number(spec.decayPerTurn ?? 1)),
    });
    attach(world, id, subjectId);
    found = { id, rec: world.get(id, SocialDisposition) };
  }

  const prevBand = found.rec.band;
  found.rec.score = Math.max(0, Math.min(100, Math.ceil(Number(found.rec.score || 0) + amount)));
  found.rec.band = dispositionBand(found.rec.score);
  found.rec.reason = String(spec.reason || found.rec.reason || "offense");
  found.rec.lastChangedTurn = Number(world.step || 0) | 0;
  if (Number.isFinite(Number(spec.decayPerTurn))) {
    found.rec.decayPerTurn = Math.max(0, Number(spec.decayPerTurn));
  }

  if (found.rec.band === SOCIAL_DISPOSITION_BANDS.hostile) {
    aimAggroAtTarget(world, subjectId, targetId);
  }

  const event = Object.freeze({
    id: found.id | 0,
    subjectId,
    targetId,
    amount,
    score: found.rec.score,
    band: found.rec.band,
    previousBand: prevBand,
    reason: found.rec.reason,
  });
  emitSafe(world, "social:offense-recorded", event);
  if (prevBand !== found.rec.band) emitSafe(world, "social:disposition-changed", event);
  return event;
}

export function decaySocialDispositionRecord(world, id, rec) {
  if (!rec || !(Number(rec.score || 0) > 0) || !(Number(rec.decayPerTurn || 0) > 0)) return null;
  const prevBand = rec.band;
  rec.score = Math.max(0, Number(rec.score || 0) - Number(rec.decayPerTurn || 0));
  rec.band = dispositionBand(rec.score);
  if (prevBand !== rec.band) {
    const event = Object.freeze({
      id: id | 0,
      subjectId: rec.subjectId | 0,
      targetId: rec.targetId | 0,
      score: rec.score,
      band: rec.band,
      previousBand: prevBand,
      reason: rec.reason,
    });
    emitSafe(world, "social:disposition-changed", event);
    return event;
  }
  return null;
}

