import { assert, assertEquals } from "jsr:@std/assert";
import { World } from "../src/lib/ecs-js/index.js";
import { AggroState, AGGRO_LEVELS } from "../src/rules/components/AggroState.js";
import { Faction } from "../src/rules/components/Faction.js";
import { Position } from "../src/rules/components/Position.js";
import { SocialDisposition } from "../src/rules/components/SocialDisposition.js";
import { Vitality } from "../src/rules/components/Vitality.js";
import {
  findSocialDisposition,
  isEntityHostile,
  recordSocialOffense,
} from "../src/rules/utils/socialDisposition.js";
import {
  installSocialDispositionListeners,
  socialDispositionSystem,
} from "../src/rules/systems/socialDispositionSystem.js";

function addActor(world, faction, x, y) {
  const id = world.create();
  world.add(id, Faction, { key: faction });
  world.add(id, Position, { x, y });
  world.add(id, Vitality, { hp: 20, maxHp: 20 });
  world.add(id, AggroState, {});
  return id;
}

Deno.test("social offense escalates an NPC to hostile aggro without changing faction", () => {
  const world = new World({ seed: 1 });
  const player = addActor(world, "player", 5, 5);
  const shopkeeper = addActor(world, "shopkeeper", 7, 5);

  const event = recordSocialOffense(world, {
    subjectId: shopkeeper,
    targetId: player,
    amount: 75,
    reason: "polymorph",
    decayPerTurn: 0,
  });

  assert(event, "offense should be recorded");
  assertEquals(world.get(shopkeeper, Faction).key, "shopkeeper");
  assertEquals(findSocialDisposition(world, shopkeeper, player).rec.band, "hostile");
  assertEquals(isEntityHostile(world, shopkeeper, player), true);
  assertEquals(world.get(shopkeeper, AggroState).alertLevel, AGGRO_LEVELS.hunting);
  assertEquals(world.get(shopkeeper, AggroState).lastKnownX, 5);
});

Deno.test("shop claims feed social disposition through the shared listener", () => {
  const world = new World({ seed: 2 });
  installSocialDispositionListeners(world);
  const player = addActor(world, "player", 1, 1);
  const shopkeeper = addActor(world, "shopkeeper", 2, 1);

  world.emit("shop:claim-recorded", {
    actorId: player,
    shopkeeperId: shopkeeper,
    severity: 3,
    reason: "teleport_exit",
  });

  const found = findSocialDisposition(world, shopkeeper, player);
  assert(found, "shop claim should create a disposition record");
  assertEquals(found.rec.score, 60);
  assertEquals(found.rec.band, "angry");
});

Deno.test("social disposition decays and can forgive below hostility", () => {
  const world = new World({ seed: 3 });
  const player = addActor(world, "player", 1, 1);
  const townsperson = addActor(world, "townfolk", 3, 1);
  recordSocialOffense(world, {
    subjectId: townsperson,
    targetId: player,
    amount: 72,
    reason: "damage",
    decayPerTurn: 10,
  });

  for (let i = 0; i < 4; i++) socialDispositionSystem(world);

  const rec = findSocialDisposition(world, townsperson, player).rec;
  assert(rec.score < 70, "score should decay below hostile threshold");
  assertEquals(rec.band, "suspicious");
  assertEquals(isEntityHostile(world, townsperson, player), false);
});

Deno.test("damage to a social actor records an offense once while non-hostile", () => {
  const world = new World({ seed: 4 });
  installSocialDispositionListeners(world);
  const player = addActor(world, "player", 1, 1);
  const townsperson = addActor(world, "townfolk", 3, 1);

  world.emit("damaged", {
    source: player,
    target: townsperson,
    amount: 12,
    cause: "spell:smite",
  });

  const records = [...world.query(SocialDisposition)];
  assertEquals(records.length, 1);
  assertEquals(records[0][1].subjectId, townsperson);
  assertEquals(records[0][1].targetId, player);
  assertEquals(records[0][1].band, "suspicious");
});

