+  confirm.style.borderColor = '#a85858';
+  confirm.style.background = '#3a1518';
+  confirm.addEventListener('click', () => {
+    const action = data?.action || null;
+    if (action) {
+      window.dispatchEvent(new CustomEvent('ui:confirmActionAccepted', { detail: { action } }));
+    }
