        const dodgeChance = defSnapshot.evade / (defSnapshot.evade + 20);
        const dodgeRoll = r();
        if (dodgeRoll < dodgeChance) {
            const dpos = world.get(target, Position);
            emitSafe(world, 'combat:dodge', {
                defender: target,
                attacker: source,
